// Informer le background.js que le content script est chargé
browser.runtime.sendMessage({ action: "contentScriptReady", url: window.location.href })
  .catch(() => {});

// ── i18n: module partagé i18n.js (chargé avant ce script par le manifeste) ───
// La langue est résolue à chaque affichage de modale (voir le listener plus bas)

function tc(key, vars = {}) {
  return NxI18n.t(key, vars);
}

// Variante de tc() qui renvoie des noeuds DOM: les valeurs sont toujours insérées comme texte
// (jamais interprétées comme du HTML). Une valeur { strong: x } est rendue en gras.
function tcNodes(key, vars = {}) {
  const fragment = document.createDocumentFragment();
  const template = tc(key);
  let last = 0;
  for (const m of template.matchAll(/\{(\w+)\}/g)) {
    fragment.append(template.slice(last, m.index));
    const value = vars[m[1]];
    if (value && typeof value === 'object' && 'strong' in value) {
      const strong = document.createElement('strong');
      strong.textContent = String(value.strong);
      fragment.append(strong);
    } else if (value !== undefined) {
      fragment.append(String(value));
    } else {
      fragment.append(m[0]);
    }
    last = m.index + m[0].length;
  }
  fragment.append(template.slice(last));
  return fragment;
}

// Insère un texte contenant des <br> sans passer par le parseur HTML: chaque <br> devient un vrai
// élément <br>, le reste est inséré comme texte brut (jamais interprété comme du HTML).
function appendTextWithBreaks(parent, text) {
  const parts = String(text == null ? '' : text).split(/<br\s*\/?>/i);
  parts.forEach((part, i) => {
    if (i > 0) parent.appendChild(document.createElement('br'));
    if (part) parent.appendChild(document.createTextNode(part));
  });
}
// ─────────────────────────────────────────────────────────────────────────────

function getDomainFromUrl(url) {
  try {
    const hostname = new URL(url).hostname;
    return hostname.replace('www.', '');
  } catch (e) {
    return url;
  }
}

// Configuration des styles par type de notification
const NOTIFICATION_STYLES = {
 'genai': {
    backgroundColor: 'rgb(141, 141, 141)',
    buttonColor: 'rgb(248, 134, 68)',
    imageData: ""
  },
  'redflag': {
    backgroundColor: 'rgb(141, 141, 141)',
    buttonColor: 'rgb(248, 134, 68)',
    imageData: ""
  },
  'amf': {
    backgroundColor: 'rgb(141, 141, 141)',
    buttonColor: 'rgb(248, 134, 68)',
    imageData: ""
  },
  'idn_homograph': {
    backgroundColor: 'rgb(141, 141, 141)',
    buttonColor: 'rgb(248, 134, 68)',
    imageData: ""
  }
};

// Variable pour éviter les doublons de notifications
let notificationDisplayed = false;

// Fonction pour vérifier si un domaine est ignoré (externalisée)
async function isDomainIgnored(domain, category) {
  try {
    const storageKey = `ignoredDomains_${category}`;
    const result = await browser.storage.local.get(storageKey);
    const ignoredDomains = result[storageKey] || [];
    return ignoredDomains.includes(domain);
  } catch (error) {
    return false;
  }
}

// Fonction pour créer le conteneur principal avec Shadow DOM
function createNotificationHost() {
  // Supprimer les anciennes notifications
  document.querySelectorAll('[id^="nx-alert-"], [id="extension-host"]').forEach(el => el.remove());

  const randomId = `nx-alert-${Date.now()}-${Math.floor(Math.random() * 10000)}`;
  const host = document.createElement('div');
  host.id = randomId;
  
  host.style.cssText = `
    display: block !important;
    visibility: visible !important;
    opacity: 1 !important;
    position: fixed !important;
    top: 0 !important;
    left: 0 !important;
    width: 100% !important;
    height: 100% !important;
    z-index: 2147483647 !important;
    pointer-events: auto !important;
  `;
  
  const shadow = host.attachShadow({mode: 'closed'});
  
  // Ajouter les styles CSS
  const style = document.createElement('style');
  style.textContent = `
    :host {
      all: initial;
      display: block !important;
      visibility: visible !important;
      opacity: 1 !important;
    }
    
    #extension-notification {
      position: fixed !important;
      top: 50% !important;
      left: 50% !important;
      transform: translate(-50%, -50%) !important;
      padding: 30px !important;
      border-radius: 10px !important;
      max-width: 800px !important;
      width: 90% !important;
      box-sizing: border-box !important;
      background-color: rgb(141, 141, 141) !important;
      border: 2px solid rgb(255, 255, 255) !important;
      color: rgb(255, 255, 255) !important;
      font-family: Arial, sans-serif !important;
      font-size: 14px !important;
      overflow: hidden !important;
      max-height: 80vh !important;
      overflow-y: auto !important;
      display: block !important;
      visibility: visible !important;
      opacity: 1 !important;
      z-index: 2147483647 !important;
    }
    
    button {
      cursor: pointer !important;
      font-family: Arial, sans-serif !important;
      display: inline-block !important;
      visibility: visible !important;
      opacity: 1 !important;
    }
    
    label {
      display: flex !important;
      align-items: center !important;
      gap: 5px !important;
      color: white !important;
      font-family: Arial, sans-serif !important;
      visibility: visible !important;
      opacity: 1 !important;
    }
    
    input[type="checkbox"] {
      margin: 0 !important;
      visibility: visible !important;
      opacity: 1 !important;
      display: inline-block !important;
    }
  `;
  
  shadow.appendChild(style);
  
  return { host, shadow, randomId };
}

// Fonction pour créer une notification individuelle
function createSingleNotification(match, index, totalCount) {
  const styles = NOTIFICATION_STYLES[match.category] || NOTIFICATION_STYLES['genai'];
  const notificationDiv = document.createElement('div');
  
  if (index < totalCount - 1) {
    notificationDiv.style.cssText = `
      margin-bottom: 20px !important;
      padding-bottom: 20px !important;
      border-bottom: 1px solid rgba(255, 255, 255, 0.2) !important;
    `;
  }
  
  const innerDiv = document.createElement('div');
  innerDiv.style.cssText = `
    display: flex !important;
    align-items: center !important;
    gap: 15px !important;
    background-color: ${styles.backgroundColor} !important;
    padding: 15px !important;
    border-radius: 8px !important;
  `;
  
  const img = document.createElement('img');
  img.src = `data:image/png;base64,${styles.imageData}`;
  img.style.cssText = 'width: 64px !important; height: 64px !important;';
  
  const textDiv = document.createElement('div');
  textDiv.style.cssText = 'flex: 1 !important; text-align: left !important;';
  
  const messagePara = document.createElement('p');
  messagePara.style.cssText = 'margin: 0 !important; white-space: pre-wrap !important;';
  appendTextWithBreaks(messagePara, match.config.message);

  // Ajouter les détails des caractères homographes si disponibles
  if (match.category === 'idn_homograph') {
    const detailsDiv = document.createElement('div');
    detailsDiv.style.cssText = 'margin-top: 15px !important; padding: 10px !important; background-color: rgba(0,0,0,0.2) !important; border-radius: 5px !important;';

    if (match.homographData && match.homographData.length > 0) {
      const detailsTitle = document.createElement('p');
      detailsTitle.style.cssText = 'margin: 0 0 10px 0 !important; font-weight: bold !important;';
      detailsTitle.textContent = tc('notification.idn_suspicious_chars_title');
      detailsDiv.appendChild(detailsTitle);

      match.homographData.forEach((charData, idx) => {
        const charDetail = document.createElement('p');
        charDetail.style.cssText = 'margin: 5px 0 !important; font-size: 13px !important;';
        charDetail.replaceChildren(tcNodes('notification.idn_char_detail', { char: { strong: charData.char }, script: charData.script, unicode: charData.unicode, latinEquivalent: { strong: charData.latinEquivalent } }));
        detailsDiv.appendChild(charDetail);
      });
    } else {
      // Domaine Punycode sans caractères suspects identifiés - afficher tous les caractères non-ASCII
      // Utiliser le domaine décodé envoyé par le service worker
      const decodedDomain = match.decodedDomain || window.location.hostname;

      // Collecter tous les caractères non-ASCII uniques
      const nonAsciiChars = [];
      for (let i = 0; i < decodedDomain.length; i++) {
        const char = decodedDomain[i];
        const code = char.charCodeAt(0);
        if (code > 127 && !nonAsciiChars.includes(char)) {
          nonAsciiChars.push(char);
        }
      }

      const infoTitle = document.createElement('p');
      infoTitle.style.cssText = 'margin: 0 0 10px 0 !important; font-weight: bold !important;';
      infoTitle.textContent = tc('notification.idn_domain_info', { chars: nonAsciiChars.join(', ') });
      detailsDiv.appendChild(infoTitle);

      // Parcourir tous les caractères et afficher leurs détails
      for (let i = 0; i < decodedDomain.length; i++) {
        const char = decodedDomain[i];
        const code = char.charCodeAt(0);

        if (code > 127) { // Uniquement les caractères non-ASCII
          const charDetail = document.createElement('p');
          charDetail.style.cssText = 'margin: 5px 0 !important; font-size: 13px !important;';
          const unicodeStr = 'U+' + code.toString(16).toUpperCase().padStart(4, '0');
          charDetail.replaceChildren(tcNodes('notification.idn_char_info', { char: { strong: char }, unicode: unicodeStr }));
          detailsDiv.appendChild(charDetail);
        }
      }
    }

    messagePara.appendChild(detailsDiv);
  }

  const buttonDiv = document.createElement('div');
  buttonDiv.style.cssText = 'margin-top: 10px !important;';
  
  const infoButton = document.createElement('button');
  infoButton.className = 'info-btn';
  infoButton.dataset.url = match.config.infoUrl;
  infoButton.dataset.category = match.category;
  infoButton.style.cssText = `
    padding: 8px 16px !important;
    background: ${styles.buttonColor} !important;
    color: white !important;
    border: none !important;
    border-radius: 4px !important;
    cursor: pointer !important;
  `;
  infoButton.textContent = tc('notification.more_info_button');
  
  buttonDiv.appendChild(infoButton);
  textDiv.appendChild(messagePara);
  textDiv.appendChild(buttonDiv);
  innerDiv.appendChild(img);
  innerDiv.appendChild(textDiv);
  notificationDiv.appendChild(innerDiv);
  
  return notificationDiv;
}

// Fonction pour créer la section de contrôles (checkbox + bouton fermer)
function createControlsSection() {
  const checkboxContainer = document.createElement('div');
  checkboxContainer.style.cssText = `
    margin-top: 15px !important;
    display: flex !important;
    align-items: center !important;
    gap: 10px !important;
  `;
  
  const checkboxLabel = document.createElement('label');
  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.id = 'dont-show-again';
  checkbox.style.cssText = 'margin: 0 !important;';
  
  checkboxLabel.appendChild(checkbox);
  checkboxLabel.appendChild(document.createTextNode(tc('notification.no_alert_checkbox')));
  checkboxContainer.appendChild(checkboxLabel);
  
  const closeButtonContainer = document.createElement('div');
  closeButtonContainer.style.cssText = `
    display: flex !important;
    justify-content: center !important;
    margin-top: 15px !important;
  `;
  
  const closeButton = document.createElement('button');
  closeButton.id = 'close-btn';
  closeButton.style.cssText = `
    padding: 8px 16px !important;
    background: rgb(248, 134, 68) !important;
    color: white !important;
    border: none !important;
    border-radius: 4px !important;
    cursor: pointer !important;
  `;
  closeButton.textContent = tc('notification.close_button');
  closeButtonContainer.appendChild(closeButton);
  
  return { checkboxContainer, closeButtonContainer, checkbox, closeButton };
}

// Fonction pour gérer la fermeture et la sauvegarde des préférences
async function handleNotificationClose(checkbox, matches, currentUrl, host) {
  if (checkbox.checked) {
    const domain = getDomainFromUrl(currentUrl);
    for (const match of matches) {
      const storageKey = `ignoredDomains_${match.category}`;
      try {
        const result = await browser.storage.local.get(storageKey);
        const ignoredDomains = result[storageKey] || [];
        if (!ignoredDomains.includes(domain)) {
          ignoredDomains.push(domain);
          await browser.storage.local.set({ [storageKey]: ignoredDomains });
        }
      } catch (error) {
        // Ignorer les erreurs de storage
      }
    }
  }
  
  host.remove();
  notificationDisplayed = false;
}

// Fonction pour créer un iframe de fallback
function createFallbackIframe() {
  const iframe = document.createElement('iframe');
  iframe.id = `nx-frame-${Date.now()}`;
  iframe.style.cssText = `
    position: fixed !important;
    top: 0 !important;
    left: 0 !important;
    width: 100% !important;
    height: 100% !important;
    border: none !important;
    z-index: 2147483647 !important;
    background: transparent !important;
    display: block !important;
    visibility: visible !important;
    opacity: 1 !important;
  `;
  
  document.documentElement.appendChild(iframe);
  
  try {
    const iframeDoc = iframe.contentDocument || iframe.contentWindow.document;
    iframeDoc.documentElement.replaceChildren();
    
    const iframeStyle = iframeDoc.createElement('style');
    iframeStyle.textContent = `
      body {
        margin: 0;
        padding: 0;
        overflow: hidden;
        background-color: rgba(0, 0, 0, 0.5);
        display: flex;
        justify-content: center;
        align-items: center;
        height: 100vh;
      }
    `;
    
    iframeDoc.head.appendChild(iframeStyle);
    
    const alertContainer = iframeDoc.createElement('div');
    alertContainer.style.cssText = `
      background-color: rgb(141, 141, 141);
      padding: 20px;
      border-radius: 10px;
      max-width: 800px;
      width: 90%;
      color: white;
      font-family: Arial, sans-serif;
      text-align: center;
    `;
    
    // Construit avec le DOM de l'iframe (iframeDoc): aucun HTML n'est analysé
    const makeText = (tag, text) => { const el = iframeDoc.createElement(tag); el.textContent = text; return el; };
    const closeBtnEl = makeText('button', tc('notification.close_button'));
    closeBtnEl.style.cssText = 'padding: 8px 16px; background: rgb(248, 134, 68); color: white; border: none; border-radius: 4px; cursor: pointer; margin-top: 10px;';
    alertContainer.append(
      makeText('h3', tc('notification.security_alert_title')),
      makeText('p', tc('notification.security_alert_blocked')),
      makeText('p', tc('notification.security_alert_watchlist')),
      closeBtnEl
    );
    
    iframeDoc.body.appendChild(alertContainer);
    
    const closeBtn = alertContainer.querySelector('button');
    closeBtn.addEventListener('click', () => {
      iframe.remove();
      notificationDisplayed = false;
    });
    
  } catch (error) {
    iframe.remove();
    notificationDisplayed = false;
  }
}

// Fonction principale pour créer la notification
async function createNotificationBlock(matches, currentUrl) {
  if (notificationDisplayed) {
    return;
  }
  
  notificationDisplayed = true;
  
  if (!matches || matches.length === 0) {
    notificationDisplayed = false;
    return;
  }

  // Filtrer les correspondances pour exclure les domaines ignorés
  const filteredMatches = [];
  for (const match of matches) {
    const domain = getDomainFromUrl(currentUrl);
    const isIgnored = await isDomainIgnored(domain, match.category);
    
    if (!isIgnored) {
      filteredMatches.push(match);
    }
  }

  if (filteredMatches.length === 0) {
    notificationDisplayed = false;
    return;
  }

  // Créer le conteneur principal
  const { host, shadow, randomId } = createNotificationHost();
  
  // Créer le conteneur principal pour la notification
  const block = document.createElement('div');
  block.id = 'extension-notification';
  
  // Créer le conteneur des notifications
  const notificationsContainer = document.createElement('div');
  notificationsContainer.style.cssText = 'margin-bottom: 20px !important;';
  
  // Ajouter chaque notification
  filteredMatches.forEach((match, index) => {
    const notificationElement = createSingleNotification(match, index, filteredMatches.length);
    notificationsContainer.appendChild(notificationElement);
  });
  
  block.appendChild(notificationsContainer);
  
  // Créer les contrôles (checkbox + bouton fermer)
  const { checkboxContainer, closeButtonContainer, checkbox, closeButton } = createControlsSection();
  block.appendChild(checkboxContainer);
  block.appendChild(closeButtonContainer);
  
  // Ajouter le bloc au shadow DOM
  shadow.appendChild(block);
  
  // Gestion des clics sur les boutons "Plus d'infos"
  shadow.querySelectorAll('.info-btn').forEach(button => {
    button.addEventListener('click', () => {
      window.open(button.dataset.url, '_blank');
    });
  });
  
  // Gestion du bouton de fermeture
  closeButton.addEventListener('click', () => {
    closeButton.removeEventListener('click', arguments.callee);
    handleNotificationClose(checkbox, matches, currentUrl, host);
  });
  
  // Ajouter au DOM
  document.body.appendChild(host);
  
  // Vérification de blocage avec fallback iframe
  setTimeout(() => {
    if (!document.getElementById(randomId) || 
        window.getComputedStyle(host).display === 'none' || 
        window.getComputedStyle(host).visibility === 'hidden') {
      createFallbackIframe();
    }
  }, 100);
}

// Listener principal pour les notifications
browser.runtime.onMessage.addListener((request, sender) => {
  if (request.action === "showNotification" && request.matches) {
    const currentUrl = window.location.href;

    try {
      // init() est instantané si la langue n'a pas changé; sinon elle est relue (voir i18n.js)
      NxI18n.init().catch(() => {}).then(() => createNotificationBlock(request.matches, currentUrl));
      return Promise.resolve({status: "Notifications affichées"});
    } catch (error) {
      notificationDisplayed = false;
      return Promise.resolve({status: "Erreur de notification"});
    }
  } else if (request.action === "checkReady") {
    return Promise.resolve({status: "ready", url: window.location.href});
  } else if (request.action === "checkAlive") {
    return Promise.resolve({status: "alive", url: window.location.href});
  }
  
  return Promise.resolve(undefined);
});

// Gestionnaire d'événements pour la visibilité de la page
document.addEventListener('visibilitychange', () => {
  if (document.visibilityState === 'visible') {
    browser.runtime.sendMessage({ 
      action: "pageRevisited", 
      url: window.location.href 
    }).catch(() => {});
  }
});